          "default": "./dist/cjs/Discovery.js"
        }
      },
      "./Executable": {
        "import": {
          "types": "./dist/esm/Executable.d.ts",
          "default": "./dist/esm/Executable.js"
        },
        "require": {
          "types": "./dist/cjs/Executable.d.ts",
          "default": "./dist/cjs/Executable.js"
        }
      },
      "./MarkdownFlow": {
        "import": {
          "types": "./dist/esm/MarkdownFlow.d.ts",
          "default": "./dist/esm/MarkdownFlow.js"
        },
        "require": {
          "types": "./dist/cjs/MarkdownFlow.d.ts",
          "default": "./dist/cjs/MarkdownFlow.js"
        }
      },
      "./ModuleFlow": {
        "import": {
          "types": "./dist/esm/ModuleFlow.d.ts",
          "default": "./dist/esm/ModuleFlow.js"
        },
        "require": {
